**Customer Service Function in Python**
=====================================

Below is an example of a Python function that simulates a customer service system. This function allows customers to view their order history, place new orders, and cancel existing orders.

```python
class CustomerService:
    def __init__(self):
        self.orders = {}

    def view_order_history(self, customer_id):
        """View the order history of a customer."""
        if customer_id in self.orders:
            return self.orders[customer_id]
        else:
            return "No orders found for this customer."

    def place_order(self, customer_id, order_details):
        """Place a new order for a customer."""
        if customer_id in self.orders:
            self.orders[customer_id].append(order_details)
        else:
            self.orders[customer_id] = [order_details]
        return f"Order placed successfully for customer {customer_id}."

    def cancel_order(self, customer_id, order_id):
        """Cancel an existing order for a customer."""
        if customer_id in self.orders:
            if order_id in self.orders[customer_id]:
                self.orders[customer_id].remove(order_id)
                return f"Order {order_id} cancelled successfully for customer {customer_id}."
            else:
                return f"No order found with ID {order_id} for customer {customer_id}."
        else:
            return f"No orders found for customer {customer_id}."


def main():
    customer_service = CustomerService()

    while True:
        print("1. View Order History")
        print("2. Place New Order")
        print("3. Cancel Order")
        print("4. Exit")

        choice = input("Choose an option: ")

        if choice == "1":
            customer_id = input("Enter customer ID: ")
            print(customer_service.view_order_history(customer_id))
        elif choice == "2":
            customer_id = input("Enter customer ID: ")
            order_details = input("Enter order details: ")
            print(customer_service.place_order(customer_id, order_details))
        elif choice == "3":
            customer_id = input("Enter customer ID: ")
            order_id = input("Enter order ID: ")
            print(customer_service.cancel_order(customer_id, order_id))
        elif choice == "4":
            break
        else:
            print("Invalid option. Please choose a valid option.")


if __name__ == "__main__":
    main()
```

**Example Use Cases:**

1.  **View Order History:**

    *   Choose option 1 from the main menu.
    *   Enter the customer ID when prompted.
    *   The function will display the order history for the specified customer.

2.  **Place New Order:**

    *   Choose option 2 from the main menu.
    *   Enter the customer ID and order details when prompted.
    *   The function will place a new order for the specified customer.

3.  **Cancel Order:**

    *   Choose option 3 from the main menu.
    *   Enter the customer ID and order ID when prompted.
    *   The function will cancel the specified order for the specified customer.

This code provides a basic structure for a customer service system and can be extended to include additional features and functionality as needed.

Here's a Python function that uses a stack to implement a basic calculator:

```python
class Stack:
    def __init__(self):
        self.stack = []

    def push(self, value):
        self.stack.append(value)

    def pop(self):
        if not self.is_empty():
            return self.stack.pop()
        else:
            return None

    def is_empty(self):
        return len(self.stack) == 0

    def peek(self):
        if not self.is_empty():
            return self.stack[-1]
        else:
            return None


class Calculator:
    def __init__(self):
        self.stack = Stack()

    def push(self, value):
        self.stack.push(value)

    def pop(self):
        return self.stack.pop()

    def is_empty(self):
        return self.stack.is_empty()

    def peek(self):
        return self.stack.peek()

    def calculate(self, expression):
        # Split the expression into numbers and operators
        tokens = []
        current_token = ""
        for char in expression:
            if char in "+-*/":
                if current_token:
                    tokens.append(int(current_token))
                    current_token = ""
                tokens.append(char)
            else:
                current_token += char
        if current_token:
            tokens.append(int(current_token))

        # Evaluate the expression
        for token in tokens:
            if token == "+":
                self.push(self.pop() + self.pop())
            elif token == "-":
                self.push(self.pop() - self.pop())
            elif token == "*":
                self.push(self.pop() * self.pop())
            elif token == "/":
                self.push(self.pop() / self.pop())

        # Return the final result
        return self.pop()


# Example usage:
calculator = Calculator()
expression = "2+3*4"
result = calculator.calculate(expression)
print(f"Result: {result}")
```

This code defines a `Stack` class to manage the stack operations and a `Calculator` class to perform the actual calculation. The `calculate` method splits the input expression into numbers and operators, evaluates the expression using the stack operations, and returns the final result.

Here's a Python function that uses a stack to implement a basic calculator:

```python
class Stack:
    def __init__(self):
        self.stack = []

    def push(self, value):
        self.stack.append(value)

    def pop(self):
        if not self.is_empty():
            return self.stack.pop()
        else:
            return None

    def is_empty(self):
        return len(self.stack) == 0

    def peek(self):
        if not self.is_empty():
            return self.stack[-1]
        else:
            return None


class Calculator:
    def __init__(self):
        self.stack = Stack()

    def push(self, value):
        self.stack.push(value)

    def pop(self):
        return self.stack.pop()

    def is_empty(self):
        return self.stack.is_empty()

    def peek(self):
        return self.stack.peek()

    def calculate(self, expression):
        # Split the expression into numbers and operators
        tokens = []
        current_token = ""
        for char in expression:
            if char in "+-*/":
                if current_token:
                    tokens.append(int(current_token))
                    current_token = ""
                tokens.append(char)
            else:
                current_token += char
        if current_token:
            tokens.append(int(current_token))

        # Evaluate the expression
        for token in tokens:
            if token == "+":
                self.push(self.pop() + self.pop())
            elif token == "-":
                self.push(self.pop() - self.pop())
            elif token == "*":
                self.push(self.pop() * self.pop())
            elif token == "/":
                self.push(self.pop() / self.pop())

        # Return the final result
        return self.pop()


# Example usage:
